INSERT INTO quest_set (id, title, description, sandbox_type, category) VALUES
  (1,  '리눅스 기초 1 — 파일 탐색과 생성', '현재 위치 확인, 디렉토리 이동, 파일/디렉토리 생성과 복사를 실습합니다.', 'linux',             '리눅스'),
  (2,  '리눅스 기초 2 — 삭제·검색·권한',  '파일 삭제, 내용 확인, 문자열 검색, 권한 변경, 링크 생성을 실습합니다.',  'linux',             '리눅스'),
  (3,  '리눅스 기초 3 — 프로세스와 시스템', '프로세스 확인/종료, 디스크/메모리 확인, 환경변수 설정을 실습합니다.', 'linux',             '리눅스'),
  (4,  '리눅스 네트워크/파일 전송',         'curl, ping, scp, rsync 등 네트워크 확인과 서버 간 파일 전송을 실습합니다.', 'linux-ssh',      '리눅스'),
  (5,  'Docker 기초',                       '컨테이너 실행·중지·삭제, 이미지 관리, 로그 확인 등 Docker 기본 조작을 실습합니다.', 'docker',    '도커'),
  (6,  'k8s 기초',                          'kubectl로 Pod, Deployment, Service를 직접 조작해봅니다.', 'k8s',                           'k8s'),
  (7,  '리눅스 압축과 아카이브',            'tar, gzip, zip 등 압축/아카이브 명령어를 실습합니다. 오프라인 패키지 반입의 기초입니다.', 'linux', '리눅스'),
  (8,  'Docker 이미지 오프라인 반입',       'tar 파일로 이미지를 save/load하고 로컬 레지스트리에 push하는 현장 패턴을 실습합니다.', 'docker-persistent', '도커'),
  (9,  'Vim 기초',                          '현장에서 가장 자주 막히는 Vim 편집 패턴을 실습합니다. 열고 저장하는 것부터 설정 파일 수정까지.', 'linux', '리눅스'),
  (10, '리눅스 현장 운영',                  'systemd, rpm, 환경변수, 방화벽 등 실제 서버 운영에서 반드시 쓰는 명령어를 실습합니다.', 'linux-systemd', '리눅스'),
  (11, 'Docker 이미지 빌드',               'Dockerfile 작성부터 이미지 빌드, 태깅까지 이미지를 직접 만드는 과정을 실습합니다.', 'docker', '도커'),
  (12, 'k8s ConfigMap과 Secret',           'ConfigMap과 Secret을 생성하고 Pod에 환경변수와 볼륨으로 주입하는 패턴을 실습합니다.', 'k8s', 'k8s'),
  (13, 'k8s 스토리지와 네트워크',          'PersistentVolume/PVC로 데이터를 영속 저장하고 port-forward로 클러스터 내부 서비스에 접근하는 패턴을 실습합니다.', 'k8s', 'k8s'),
  (14, 'Helm 기초',                         'Helm으로 차트를 설치하고 값을 커스터마이징하는 현장 패턴을 실습합니다. repo 추가부터 업그레이드·롤백까지.', 'k8s', 'k8s'),
  (15, '리눅스 로그와 텍스트 처리',       '로그에서 필요한 줄과 숫자를 뽑아내는 현장 패턴을 실습합니다. grep, 리다이렉션, sort/uniq, awk, sed.', 'linux', '리눅스'),
  (16, '리눅스 장애 진단 실전',          '디스크 부족, 과다 CPU, 포트 충돌, 권한 오류 등 장애 상황에서 원인을 찾고 해결하는 패턴을 실습합니다.', 'linux', '리눅스'),
  (17, '리눅스 쉘 스크립트 기초', '변수와 인자, 조건문, 반복문, 종료 코드로 현장에서 쓰는 작은 쉘 스크립트를 직접 작성합니다.', 'linux', '리눅스'),
  (18, '리눅스 네트워크 진단', 'curl, nc, ss, /etc/hosts 로 서비스가 응답하는지, 포트가 열려 있는지, 이름이 풀리는지 확인하는 현장 패턴을 실습합니다.', 'linux', '리눅스'),
  (19, 'kubectl 속도와 실전', 'dry-run으로 YAML 뼈대 만들기, 명령형 수정, jsonpath, custom-columns, explain, patch 등 시간 제한 실기(CKA 등)에서 점수를 가르는 kubectl 손기술을 실습합니다.', 'k8s', 'k8s'),
  (20, 'k8s 일상 운영 기본기', '노드·IP 확인, exec, 로그, 이벤트, 라벨 셀렉터, 롤아웃 이력·재시작, YAML 백업 등 매일 쓰는 kubectl 기본 명령을 실습합니다.', 'k8s', 'k8s'),
  (21, '리눅스 쉘 기본기와 사용자·권한', '와일드카드, 인용부호, xargs, tee, diff, alias, 사용자·그룹, su, umask, 하드링크 등 매일 쓰는 쉘 기본기를 실습합니다.', 'linux', '리눅스'),
  (22, 'k8s 워크로드 기본', 'Job·CronJob, DaemonSet, requests/limits, 프로브, nodeSelector, initContainers, HPA 등 워크로드의 기본 구성 요소를 실습합니다.', 'k8s', 'k8s'),
  (23, 'k8s 트러블슈팅 실전', '깨진 워크로드의 원인을 describe·logs·events 로 찾아 직접 고칩니다. 이미지 오타, 셀렉터·포트 불일치, CrashLoopBackOff, Pending, 설정 참조 오류 등.', 'k8s', 'k8s'),
  (24, '리눅스 패키지와 systemd 로그', 'rpm 으로 패키지를 조회·검증하고, journalctl·logger 로 로그를 찾고, systemd 유닛을 만들어 시작하고 실패 원인을 찾는 현장 패턴을 실습합니다.', 'linux-systemd', '리눅스'),
  (25, 'k8s 서비스와 네트워킹', 'Service 유형, 엔드포인트, 클러스터 DNS, Ingress, NetworkPolicy, Headless Service 등 k8s 네트워킹의 기본 구성을 실습합니다.', 'k8s', 'k8s'),
  (26, 'k8s 스케줄링과 배포 전략', 'taint·toleration, nodeAffinity, podAntiAffinity, 롤링 업데이트 전략, StatefulSet, PodDisruptionBudget, graceful shutdown, kubectl diff 등 Pod 배치와 배포 방식을 다루는 기본기를 실습합니다.', 'k8s', 'k8s'),
  (27, '리눅스 성능과 스토리지(NFS) 점검', '메모리·CPU·로드를 점검하고 df 계열 출력을 읽으며, NFS 마운트 설정(fstab, exports)과 출력을 해석하는 현장 점검 패턴을 실습합니다.', 'linux', '리눅스'),
  (28, '리눅스 명령어 확인 퀴즈', '명령어의 옵션 의미, 권한과 출력 읽기, 용량·메모리 해석, 종료 코드, NFS 장애 해석까지 객관식으로 확인합니다. 정답과 함께 오답이 왜 틀렸는지 해설을 봅니다.', 'quiz', '리눅스'),
  (29, 'k8s CKA 개념·명령 퀴즈', 'Pod/Deployment/Service, 장애 상태(CrashLoopBackOff, Pending, OOMKilled), 프로브, 롤백, Secret, kubectl 사용법을 CKA 연습처럼 객관식으로 확인합니다.', 'quiz', 'k8s'),
  (30, '리눅스 터미널로 확인하고 고르기', '터미널에서 직접 명령을 실행해 로그, 디렉터리 용량, 권한, 종료 코드, 설정 파일을 확인하고 그 결과로 정답을 고르는 실습형 객관식입니다. 정답과 함께 오답이 왜 틀렸는지 해설을 봅니다.', 'linux', '리눅스'),
  (31, 'k8s 터미널로 확인하고 고르기', 'kubectl 로 Pod 의 실패 원인, Pending 이유, 배포 이력, Service 연결, ConfigMap·Secret 값, 라벨, 컨테이너 환경변수를 직접 확인하고 그 결과로 정답을 고르는 실습형 객관식입니다. 정답과 함께 오답이 왜 틀렸는지 해설을 봅니다.', 'k8s', 'k8s'),
  (32, '리눅스 증상의 원인을 원리로 풀기', '"안에서는 되는데 밖에서만 안 된다", "지웠는데 용량이 그대로다" 같은 현장 증상을 터미널에서 직접 재현하고, 그 **원리**(루프백 바인딩, 종료 코드와 시그널, UID 권한, 열린 파일, 이름 해석 순서, inode, 좀비 프로세스)를 객관식으로 확인합니다. 해설에서 왜 그런지와 오답이 틀린 이유를 함께 봅니다.', 'linux', '리눅스'),
  (33, 'k8s 쉬운 장애 고치기', '이미지 태그·주소 오류 고치기, ConfigMap 변경 후 재시작, Pod 개수 늘리기, 없는 StorageClass 때문에 Pending 인 PVC 고치기, 실패한 배포 되돌리기, 컨테이너 2개짜리 Pod 와 kubectl 정렬 옵션까지 현장에서 가장 자주 만나는 쉬운 장애와 기본 작업을 직접 고칩니다.', 'k8s', 'k8s'),
  (34, '리눅스 명령 연결하기: 파이프와 리다이렉션', '파이프(|)로 명령의 결과를 다른 명령에 넘기고, >, >>, <, 2> 로 입출력을 파일에 연결하고, &&, ||, ; 로 명령을 이어 실행하는 법을 연습합니다. grep, awk, sort 같은 도구를 조합하기 전에 꼭 필요한 연결 문법입니다.', 'linux', '리눅스'),
  (35, '리눅스 반복 작업 한 줄로 끝내기', '같은 일을 여러 번 해야 할 때 for 와 while read 로 한 줄에 끝내는 법을 연습합니다. 파일 여러 개 처리, 숫자 범위 반복, 확장자 일괄 변경, 서버 목록 순회, 조건으로 골라 처리하기, 반복 멈추기, 그리고 반복문이 이름의 공백에서 깨지는 이유를 다룹니다.', 'linux', '리눅스'),
  (36, '리눅스 이름으로 통신하기', '서버끼리 이름으로 통신하게 만드는 /etc/hosts 사용법(여러 서버 등록, 별칭, 옛 IP 고치기, 백업과 복구)과, 이름으로 포트에 접속되는지 확인하는 법을 연습합니다. 접속 오류 메시지가 어느 단계(이름 해석, 포트, 서비스)의 문제인지 읽고 확인 순서를 익힙니다.', 'linux', '리눅스'),
  (37, 'k8s 통신 방법 익히기', 'Pod 끼리 IP 로 통신하기와 그 한계(IP 가 바뀜), 같은 Pod 안의 localhost 통신, 임시 Pod 로 Service 통신 테스트하기, 짧은 이름이 되는 이유(resolv.conf 의 search), Service 의 port 와 targetPort, 외부 접속 방법의 선택 기준을 직접 해 보며 익힙니다.', 'k8s', 'k8s'),
  (38, 'Dockerfile 읽고 이해하기', 'Dockerfile 의 각 줄이 무슨 일을 하는지 읽고, 줄 순서와 명령을 직접 맞춰 보며 Dockerfile 을 읽는 눈을 기릅니다. 줄 순서 맞추기, 빈칸 채우기, 객관식으로 터미널 없이 풀어요.', 'quiz', '도커'),
  (39, 'docker compose 파일 읽고 이해하기', '여러 컨테이너를 한 파일로 정의하는 compose.yaml 을 읽고, 포트·의존성·볼륨·서비스 이름 통신이 무슨 뜻인지 직접 맞춰 봅니다. 빈칸 채우기, 순서 맞추기, 객관식으로 터미널 없이 풀어요.', 'quiz', '도커'),
  (42, '리눅스 기초 개념 먼저 이해하기', '파일 경로, 권한, 프로세스처럼 리눅스 실습의 바탕이 되는 개념을 터미널 없이 먼저 확인합니다. 순서 맞추기, 빈칸 채우기, 객관식으로 가볍게 풀어요.', 'quiz', '리눅스'),
  (40, 'Docker 개념 먼저 이해하기', '이미지와 컨테이너, 레지스트리, 포트 연결, 볼륨 같은 Docker 의 기본 개념을 터미널 없이 먼저 확인합니다. 순서 맞추기, 빈칸 채우기, 객관식으로 가볍게 풀어요.', 'quiz', '도커'),
  (41, 'k8s 개념 먼저 이해하기', 'Pod, Deployment, Service, Namespace, ConfigMap 과 Secret 같은 쿠버네티스의 기본 개념을 터미널 없이 먼저 확인합니다. 순서 맞추기, 빈칸 채우기, 객관식으로 가볍게 풀어요.', 'quiz', 'k8s'),
  (43, '명령 연결 개념 먼저 이해하기: 출력·오류·파이프', '명령의 정상 출력과 오류가 어디로 나가는지, `>`·`>>`·`2>&1`·파이프(`|`)·`&&`·`||` 가 무엇을 하는지 터미널 없이 먼저 이해합니다. 이 개념은 뒤의 프로세스·로그·find 실습에서 계속 쓰입니다.', 'quiz', '리눅스'),
  (44, 'find 천천히 익히기: 찾고, 걸러내고, 실행하기', '파일을 찾는 `find` 를 옵션 하나씩 익힙니다. 구조 이해부터 이름·종류·크기·시간·깊이 조건, 조건 조합(`-o`, `!`), 찾은 파일에 명령 실행(`-exec`), 삭제(`-delete`), `xargs` 연결, 여러 조건을 한꺼번에 만족하는 종합 문제까지 단계별로 연습합니다.', 'linux', '리눅스'),
  (45, '명령어 해부하기: 복사하기 전에 읽는 법', '인터넷에서 복사한 명령을 무슨 뜻인지 모른 채 붙여 넣고 있진 않나요? 명령·옵션·인자를 나눠 읽는 법, 낯선 명령을 쓸 때의 안전한 순서, 위험한 명령을 알아보는 눈, 실행 결과를 미리 짐작하는 연습을 터미널 없이 합니다.', 'quiz', '리눅스'),
  (46, 'kubectl 명령과 YAML 해부하기', 'kubectl 명령이 어떤 구조로 이루어져 있는지, Deployment YAML 의 각 부분이 무슨 뜻인지, 라벨과 셀렉터가 어떻게 이어지는지를 클러스터 없이 읽고 맞춰 봅니다. 복사해서 붙이기 전에 읽는 힘을 기릅니다.', 'quiz', 'k8s'),
  (47, '도움말로 명령 완성하기: --help 읽고 직접 찾기', '옵션을 외우는 것이 아니라 **도움말에서 찾아 쓰는 법**을 익힙니다. 정답 옵션은 알려 주지 않습니다. `명령 --help` 를 읽고, `| grep` 으로 필요한 줄만 골라 보며 명령을 스스로 완성해 보세요.', 'linux', '리눅스'),
  (48, 'grep 천천히 익히기: 글자로 줄 찾기', '파일 **안의 글자**를 찾는 `grep` 을 옵션 하나씩 익힙니다. `find`(이름·속성을 찾는 명령)와의 차이, 대소문자(`-i`), 제외(`-v`), 줄 번호(`-n`), 개수(`-c`), 단어(`-w`), 폴더 전체(`-r`, `-l`), 또는(`-E`), 일부만 뽑기(`-o`), 앞뒤 줄(`-A`/`-B`)을 연습하고 마지막에 합쳐서 씁니다. 옵션은 `--help` 에서 찾는 방법도 함께 안내합니다.', 'linux', '리눅스'),
  (49, '텍스트 도구 입문: 센다, 정렬한다, 뽑는다', '`wc`, `head`/`tail`, `sort`, `uniq`, `cut`, `tr` 을 하나씩 익히고 `|` 로 이어 "가장 많이 나온 것 찾기" 같은 일을 한 줄로 해 봅니다. 로그와 목록을 다루는 모든 작업의 기본 도구입니다.', 'linux', '리눅스'),
  (50, '따옴표·변수·치환 익히기: 쉘이 먼저 해석하는 것들', '명령은 실행되기 **전에** 쉘이 먼저 해석합니다. 작은따옴표와 큰따옴표의 차이, 변수 지정과 `$변수`, 명령 치환 `$( )`, 공백이 든 이름, `$` 를 글자 그대로 쓰기, `export` 를 연습합니다. 복사한 명령이 왜 그렇게 쓰였는지 읽는 힘이 생깁니다.', 'linux', '리눅스'),
  (52, 'Git 기초: 저장소 만들고 기록하기', 'CI/CD 의 출발점인 Git 을 터미널에서 직접 익힙니다. 사용자 설정, 저장소 만들기, 상태 확인(`status`), 기록(`add`·`commit`), 변경 확인(`diff`), 이력 보기(`log`), 일부만 커밋, `.gitignore` 까지 한 걸음씩 연습합니다.', 'linux', 'Git'),
  (51, 'HAProxy 로드밸런서 익히기: 나누고, 거르고, 확인하기', '요청을 여러 서버로 나눠 주는 HAProxy 를 직접 다뤄 봅니다. frontend·backend 구조, 문법 검사(`haproxy -c`), 서버 추가, 번갈아 분산(roundrobin), 경로별 라우팅(`use_backend`), 헬스체크, 통계 화면, 가중치를 하나씩 연습합니다.', 'linux', '미들웨어'),
  (53, 'Git 브랜치와 병합: 갈라지고 합치고 충돌 풀기', 'CI/CD 의 핵심인 브랜치 작업을 익힙니다. 브랜치 만들기와 이동(`switch`), 목록(`branch`), 병합(`merge`)의 두 종류(fast-forward, 병합 커밋), 충돌 읽고 해결하기, 합친 브랜치 정리, 긴급 수정 흐름 종합까지 연습합니다.', 'linux', 'Git'),
  (54, 'Git 원격과 협업: 복제하고 올리고 받아오기', '혼자 쓰던 Git 을 팀 작업으로 넓힙니다. 로컬과 원격의 차이, 복제(`clone`), 원격 확인(`remote -v`), 올리기(`push`, `push -u`), 받아오기(`pull`), 안전하게 확인(`fetch`), 거절된 push 풀기, 브랜치로 작업해 올리는 흐름까지 연습합니다. 원격은 샌드박스 안의 로컬 저장소로 대신합니다.', 'linux', 'Git'),
  (55, '인프라 용어 지도: RHV·RHOV·OSP·OCP 헷갈리지 않기', '레드햇·VMware 계열의 비슷해 보이는 이름들(RHV, RHOV, RHOSP/OSP, RHOSO, OCP, vSphere/vCenter, KVM, KubeVirt)을 "VM 을 관리하나, 컨테이너를 관리하나" 라는 축으로 구분합니다. 이름이 나왔을 때 어느 층의 이야기인지 바로 떠올리는 것이 목표입니다.', 'quiz', '인프라'),
  (56, 'Git 되돌리기와 복구: 실수해도 되돌릴 수 있다', '현장에서 가장 두려운 순간, "실수했다"에 대처하는 법입니다. 수정 버리기(`restore`), 스테이징 취소, 커밋 고치기(`amend`), 합치기(`reset --soft`), 이력을 지우지 않는 되돌리기(`revert`), 임시 보관(`stash`), 날린 커밋 되살리기(`reflog`), 엉뚱한 push 를 막는 `--no-track`, `cherry-pick` 을 연습합니다. 실제 현장 복구 사례를 바탕으로 했습니다.', 'linux', 'Git'),
  (57, '관측 입문: 메트릭·로그·트레이스와 도구 구분', '모니터링과 관측 가능성의 차이, 세 가지 신호(Trace·Metric·Log), Prometheus 의 pull 수집과 저장 구조, Thanos·ServiceMonitor, Loki 의 레이블 인덱싱, Promtail·Alloy·Logstash·Vector 의 구분을 문제로 정리합니다.', 'quiz', '미들웨어'),
  (58, 'Kafka 와 CDC: 토픽·파티션부터 Debezium 흐름까지', 'Kafka 의 토픽·파티션·offset, 컨슈머 그룹, 복제(Leader/Follower), 멱등 프로듀서, DLQ 와 RabbitMQ 와의 차이를 정리하고, CDC 의 개념과 binlog, Debezium 으로 변경이 Kafka 까지 흘러가는 순서와 필요한 권한을 문제로 익힙니다.', 'quiz', '미들웨어'),
  (59, 'MariaDB 복제·Galera·복구: 무엇이 어긋났는지 읽기', 'MariaDB 의 Primary-Replica 복제와 Galera Cluster(동기 복제, Certification 충돌 처리, AUTO_INCREMENT, recv_queue), failover 와 split-brain, MaxScale 구성 요소, PITR, 그리고 실제 복제 장애 복구 절차(상태 확인, 임시 skip 의 위험, dump 옵션, GTID 재연결)를 문제로 정리합니다.', 'quiz', '미들웨어'),
  (60, 'Redis 익히기: 자료구조와 만료, 카운터, 분산 락', '메모리 기반 key-value 저장소 Redis 를 `redis-cli` 로 직접 다뤄 봅니다. 값 저장과 만료(TTL), 원자적 카운터(INCR), 해시·리스트·집합·정렬된 집합 자료구조, 그리고 `SET NX EX` 로 분산 락을 잡는 기본을 연습합니다.', 'linux', '미들웨어'),
  (61, '인프라 스토리지·네트워크: Ceph, Cinder, Neutron 구분하기', '"저장소는 하나, 연결 계층이 둘" 이라는 구도로 Ceph·ODF·Cinder 를, "엔진 하나, 연결 계층 둘" 이라는 구도로 OVN·Neutron·OVN-Kubernetes 를 구분합니다. OpenStack 의 VM 프로비저닝 흐름, 테넌트, Proxmox 와의 규모 차이도 문제로 정리합니다.', 'quiz', '인프라'),
  (62, 'Elasticsearch 입문: 역색인, 샤드, refresh 와 flush', 'Elasticsearch 의 역색인, 샤드(Primary·Replica)와 클러스터 상태 색깔, 노드 역할, 색인된 문서가 저장되는 흐름(Translog, refresh, flush), Segment 불변성, 매핑(text·keyword), query 와 filter 의 차이를 문제로 정리합니다.', 'quiz', '미들웨어'),
  (63, 'HAProxy 심화: 분산 방식, 연결 제한, TLS, 이중화', 'HAProxy 의 분산 알고리즘(leastconn, source), 세션 고정, 타임아웃과 maxconn·queue, SSL Termination 과 Passthrough, SNI, 그리고 VIP·Keepalived·VRRP 로 HAProxy 자체를 이중화하는 흐름, rate limiting, retry 와 redispatch 를 문제로 정리합니다.', 'quiz', '미들웨어'),
  (64, 'CI/CD 도구 입문: Jenkins, Nexus, Harbor', 'CI 와 CD 의 구분, Jenkinsfile(pipeline·agent·stages·steps·post·when)과 controller·agent, Nexus 의 저장소 종류(hosted·proxy·group), Harbor 와 이미지 주소 읽기, 이미지를 올리고 받아 쓰는 순서, ImagePullBackOff 와 latest 태그의 위험을 문제로 정리합니다.', 'quiz', '미들웨어'),
  (65, '권한과 소유자: chmod, chown, umask', '`ls -l` 의 권한 문자열 읽기, 숫자 권한(644, 755, 600)과 기호 권한(`+x`, `o-w`), `chmod` 와 `chown`·`chgrp`, 새 파일의 기본 권한을 정하는 `umask`, 그리고 777 이 위험한 이유를 연습합니다. 복사한 명령의 권한 부분을 이해하고 고칠 수 있게 됩니다.', 'linux', '리눅스'),
  (66, 'RabbitMQ 입문: Exchange·Queue·Binding과 안정적 전달', 'RabbitMQ(AMQP)의 Exchange·Queue·Binding·routing key 구조와 exchange 타입(direct, fanout, topic), ack 와 재전달, prefetch, 재시작에도 유지하는 durable·persistent, Dead Letter Exchange, 그리고 Kafka 와 어느 상황에 무엇을 쓰는지 문제로 정리합니다.', 'quiz', '미들웨어'),
  (68, 'CDC 운영 심화: 양방향 루프 방지, 초기 동기화, 장애 복구', '두 DB 를 서로 동기화하는 양방향 CDC 를 운영할 때 마주치는 문제를 문제로 정리합니다. 무한 루프를 막는 sql_log_bin=0, PK 대역 분리, 초기 동기화 순서, DELETE·tombstone 처리, 커넥터 재시작과 offset 무효화, at-least-once 와 멱등 sink, Galera 와 CDC 의 주의점을 다룹니다.', 'quiz', '미들웨어'),
  (69, '연쇄 장애 읽기: 증상 뒤의 원인 찾기', '운영에서 흔히 겪는 연쇄 장애를 바탕으로 한 사례로, 증상에서 원인으로 거슬러 올라가는 법을 익힙니다. Kafka CPU 폭증의 진짜 원인(NetworkPolicy 로 막힌 ES), 파이프라인 구간별 유실 여부, Galera 노드 복구와 쿼럼 상실, 비대칭 라우팅, 장애 테스트 전 기록을 다룹니다.', 'quiz', '미들웨어'),
  (70, 'HAProxy 와 Istio 함께 읽기: Gateway·VirtualService', 'HAProxy 가 앞단에서 L4 로 넘기고 Istio Gateway·VirtualService 가 TLS 종단과 도메인 라우팅을 맡는 구성을 읽습니다. 트래픽 흐름, 역할 차이, TLS 패스스루, 새 서비스 추가 절차, 리다이렉트와 경로 라우팅, NodePort 연결을 다룹니다.', 'quiz', '미들웨어'),
  (71, 'Elasticsearch ILM 운영: 인덱스의 일생과 저장소', '로그·메트릭이 계속 쌓이는 Elasticsearch 를 ILM 으로 관리하는 법을 익힙니다. hot/warm/cold/delete 단계, rollover, 정책과 템플릿의 차이, 인덱스 단위 삭제, 샤드·레플리카, 쿠버네티스의 StorageClass·PV·PVC 를 다룹니다.', 'quiz', '미들웨어'),
  (67, 'Kafka 운영 심화: 복제와 안전한 쓰기, 접속 주소, 순차 재시작', 'ISR 과 acks·min.insync.replicas 로 안전하게 쓰는 법, Controller 와 파티션 Leader 의 차이, KRaft 쿼럼을 순차로 재시작하는 이유, advertised.listeners 와 HAProxy 포트 매핑, 보관정책, Kafka Connect 내부 토픽, 멱등 전달을 운영 사례 중심으로 정리합니다.', 'quiz', '미들웨어'),
  (72, 'HAProxy 활용 케이스 실습: TCP 포워딩, 도메인 분기, 이중화', '실무에서 자주 쓰는 HAProxy 구성을 샌드박스에서 직접 만들어 봅니다. Kafka 처럼 HTTP 가 아닌 트래픽을 넘기는 TCP 포워딩(브로커별 포트), 도메인별 ACL 분기, 헬스체크 경로가 틀렸을 때 고치고 reload 하기, 리다이렉트, backup 서버로 이중화하기를 연습합니다.', 'linux', '미들웨어'),
  (73, '장애 복구 절차 읽기: Galera 와 Kafka', 'Galera 노드 장애와 Kafka 브로커 장애를 복구하는 절차를 읽고 순서와 이유를 익힙니다. 단일 노드 복구 순서, 로그에서 볼 오류 패턴, SST 와 IST, 쿼럼 복구 뒤 노드를 하나씩 올리는 이유, ISR 확인, 강제 리더 선출(unclean)의 위험, 메타데이터 손상 시 백업 우선, 오프셋 초기화를 다룹니다.', 'quiz', '미들웨어'),
  (74, '메트릭 파이프라인 읽기: Prometheus → Vector → Kafka', '클러스터 내부 Prometheus 에서 federate 로 메트릭을 가져와 recording rule 로 가공하고 Vector 로 변환·집계해 Kafka 로 보내는 메트릭 파이프라인을 읽습니다. federation 과 remote_write, recording rule, Vector 의 변환 단계와 reduce, 토픽 분리, HAProxy 를 거치는 federate 통신, 토큰 권한 오류와 단계별 진단을 다룹니다.', 'quiz', '미들웨어'),
  (75, '리눅스 운영 기본기: SSH 키, 시간 동기화, NFS, 정책 라우팅', '현장 서버를 다룰 때 매일 쓰는 운영 기본기를 익힙니다. SSH 공개키/개인키 인증(키 생성, authorized_keys 등록, 권한), 클러스터에서 시간 동기화(chrony)가 중요한 이유, NFS 임시 마운트와 언마운트가 안 될 때, 비대칭 라우팅과 정책 라우팅의 임시·영구 적용을 다룹니다.', 'linux', '리눅스'),
  (76, 'Elasticsearch 심화: 검색 점수, 분석기, 샤드 운영', '검색 결과의 순서를 정하는 BM25 와 분석기(Analyzer)의 3단계, 세그먼트를 합치는 merge, 준실시간 검색과 refresh, 샤드 할당·재분배와 노드를 순차 재시작할 때의 설정, 미할당 샤드의 원인을 문제로 정리합니다.', 'quiz', '미들웨어'),
  (77, '컨테이너의 정체: 격리된 프로세스, 네임스페이스와 cgroup, 이미지 레이어', '컨테이너는 가상 컴퓨터가 아니라 **격리된 프로세스**입니다. 네임스페이스(무엇을 보는가)와 cgroup(얼마나 쓰는가), 이미지 레이어와 쓰기 시 복사(CoW), OCI·CRI·containerd, 레지스트리와 태그를 개념으로 잡고, 샌드박스 안에서 네임스페이스·PID 1·cgroup 을 직접 읽어 확인합니다.', 'linux', '도커'),
  (78, 'k8s 구조 이해하기: 컨트롤 플레인, 노드, 선언형 모델', 'kubectl 로 명령을 내리기 전에 쿠버네티스가 안에서 어떻게 움직이는지 큰 그림을 잡습니다. 컨트롤 플레인(API Server, etcd, Scheduler, Controller), 노드의 kubelet·컨테이너 런타임·kube-proxy, 선언형 모델과 reconcile, CRD 와 Operator 를 문제로 정리합니다.', 'quiz', 'k8s'),
  (79, 'k8s 스케줄링 운영 개념: Taint, drain, DaemonSet, Ingress', '노드를 점검하거나 워크로드를 배치할 때 쓰는 개념을 문제로 정리합니다. Taint 와 Toleration, Affinity 와의 방향 차이, cordon·drain·eviction 과 PodDisruptionBudget, Pod·Sidecar·DaemonSet 의 구분, Ingress·Egress 의 방향과 Gateway API 를 다룹니다.', 'quiz', 'k8s'),
  (80, 'k8s 네트워크와 외부 노출: CNI, Service, NodePort, NFS', 'Pod 가 서로, 그리고 밖과 어떻게 통신하는지 구조를 잡습니다. CNI 와 같은 노드·다른 노드 통신, Flannel 과 Calico 의 차이, NetworkPolicy, Service 가 iptables 로 L4 로드밸런싱하는 방식과 IPVS, ClusterIP·NodePort·LoadBalancer, port 와 targetPort, NFS 볼륨이 필요한 이유를 문제로 정리합니다.', 'quiz', 'k8s'),
  (81, 'DNS 와 이름 해석: 왜 깨지고 어떻게 확인하나', '"서버에 접속이 안 돼요"의 원인이 DNS 인 경우는 많습니다. DNS 가 깨지는 흔한 방식(ndots, 네거티브 캐싱, 시작 시 한 번만 resolve 하는 앱, TCP 53 차단), `/etc/hosts` 와 `dig` 결과가 달라지는 이유, UDP 의 특성, OSI 계층 용어를 개념으로 잡고, 이름 해석 순서와 `/etc/hosts` 를 샌드박스에서 직접 확인합니다.', 'linux', '리눅스'),
  (82, 'GitOps 와 k8s 위의 CI/CD: Argo CD, Jenkins Pod, 이미지 빌드', 'GitOps 와 Argo CD(Git 을 진실로 두고 클러스터가 당겨서 맞춘다), push 와 pull 배포의 차이, merge 가 배포이고 revert 가 롤백인 이유, 그리고 Jenkins·Gitea 같은 상태 있는 서비스를 Pod 로 운영할 때 달라지는 것(PVC, Recreate, agent Pod, daemon 없는 이미지 빌드, 설정의 코드화)과 IaC 도구(Pulumi)를 문제로 정리합니다.', 'quiz', '미들웨어'),
  (83, 'Redis 심화: 원자성, 안전한 락 해제, 영속화와 메모리', 'Redis 가 명령 하나는 원자적이지만 여러 명령 사이에는 다른 클라이언트가 끼어들 수 있다는 점에서 출발해, MULTI/EXEC 와 Lua 스크립트의 차이, 남의 락을 지우지 않는 안전한 락 해제, 한도 안에서만 증가하는 카운터, TTL 해제(PERSIST), AOF 영속화와 메모리 한도(eviction) 설정을 실습합니다.', 'linux', '미들웨어'),
  (84, 'HAProxy 운영 심화: 로그 읽기, 요청 제한, 차단, URI 분산', 'HAProxy 로그의 타이밍 필드로 병목을 읽고(Tw, Tc, Tr), 요청 로그를 직접 남기고, 경로 차단(403)과 요청 빈도 제한(429, stick-table), 연결 수 제한의 차이, URI 해시 분산(balance uri)을 실습합니다.', 'linux', '미들웨어'),
  (85, '프로세스와 파일시스템 이해하기: fork·exec, /proc, 커널 모드', '리눅스를 쓰는 모든 명령의 바탕이 되는 개념을 잡습니다. 프로세스를 만드는 fork 와 exec(PID 가 어떻게 변하나), 쓰기 시 복사(CoW), "모든 것은 파일이다"(/proc, /dev), 파일시스템 계층(/etc, /var, /tmp, /usr), 유저 모드와 커널 모드, 시스템 콜을 개념으로 익히고 샌드박스에서 직접 확인합니다.', 'linux', '리눅스'),
  (86, '분산 시스템 핵심 개념: 합의, 일관성, Saga, 멱등, 백프레셔', 'Kafka·etcd·데이터베이스를 이해하는 바탕이 되는 분산 시스템 개념을 정리합니다. 합의(Paxos·Raft)와 과반수(quorum), Raft 커밋과 Kafka acks 의 차이, 강한 일관성과 최종 일관성, 이벤트 기반 구조, 2PC 의 한계와 Saga(보상 트랜잭션), 멱등성, 백프레셔, 배치와 스트림 처리를 문제로 익힙니다.', 'quiz', '미들웨어'),
  (87, 'DB 내부 이해: 격리 수준, MVCC, 로그, 인덱스, EXPLAIN', '데이터베이스가 동시성과 장애 복구를 어떻게 처리하는지 InnoDB 기준으로 정리합니다. 트랜잭션 격리 수준과 dirty·non-repeatable·phantom read, Read View 와 MVCC, undo·redo·binlog 로그와 WAL, 크래시 복구 시 2단계 커밋, 복합 인덱스의 leftmost prefix 와 EXPLAIN 읽기를 문제로 익힙니다.', 'quiz', '미들웨어'),
  (88, '설정 파일 읽고 고치기: Kafka, Prometheus, Elasticsearch', 'Kafka 의 리스너 설정, Prometheus 의 scrape 설정, Elasticsearch 의 ILM 정책 JSON 을 빈칸으로 채워 읽고, 설정을 안전하게 바꾸는 순서를 익힌 뒤, 샌드박스에서 설정 파일의 오류를 직접 찾아 고칩니다. 객관식뿐 아니라 빈칸, 순서, 직접 수정으로 구성했습니다.', 'linux', '미들웨어'),
  (89, 'Kafka 명령과 출력 다루기: 만들고, 읽고, 계산하기', 'Kafka 를 다루는 CLI 명령(토픽 생성, 컨슈머 그룹 조회)과 Debezium 커넥터 설정을 빈칸으로 채워 익히고, offset 재설정의 안전한 순서를 놓아 보고, 컨슈머 lag 과 ISR 이 모자란 파티션을 샘플 출력에서 awk 로 직접 계산해 봅니다. 객관식, 빈칸, 순서, 터미널 실습을 섞었습니다.', 'linux', '미들웨어'),
  (90, '관측 쿼리와 설정 다루기: PromQL, LogQL, 메트릭 읽기', 'Prometheus 의 PromQL 과 Loki 의 LogQL 을 빈칸으로 채워 읽고, 장애를 메트릭 → 로그 → 트레이스로 좁혀 가는 순서를 놓고, Prometheus 가 노출하는 텍스트 형식의 메트릭을 grep·awk 로 직접 읽고 계산하며 알림 규칙의 오류를 고칩니다. 카디널리티가 왜 위험한지도 직접 세어 봅니다.', 'linux', '미들웨어'),
  (91, 'MariaDB 복제·Galera 점검하기: 명령 채우고, 상태 읽고, 설정 고치기', 'MariaDB 복제와 Galera 를 점검하는 명령(dump 옵션, GTID 재연결, wsrep 상태 확인)을 빈칸으로 채우고, 쿼럼을 잃었을 때 복구 순서를 놓고, 복제 상태 출력과 dump 파일에서 필요한 값을 직접 뽑아 읽고, AUTO_INCREMENT 설정의 오류를 고칩니다. 객관식, 빈칸, 순서, 터미널 실습을 섞었습니다.', 'linux', '미들웨어'),
  (92, '서비스 메시 YAML 읽고 고치기: Gateway, VirtualService', 'Istio 같은 서비스 메시에서 외부 트래픽을 받는 Gateway 와 요청을 나누는 VirtualService 의 YAML 을 빈칸으로 채워 읽고, 새 서비스를 노출하는 순서를 놓고, 이름 오타와 가중치 합계 같은 흔한 오류를 직접 고칩니다. 객관식, 빈칸, 순서, 터미널 실습을 섞었습니다.', 'linux', '미들웨어'),
  (93, 'Jenkins 운영 실무: PVC 속 결과물 찾기, 도구 컨테이너로 git 쓰기', '쿠버네티스에서 Jenkins 를 운영할 때 자주 부딪히는 일을 익힙니다. 빌드 결과물이 들어 있는 PVC 폴더를 찾는 흐름(Pod → PVC → PV → 실제 경로), agent Pod 방식에서 workspace 가 어디에 있는지, PVC 가 가득 찼을 때 큰 job 찾기, 그리고 호스트에 git 이 없을 때 git 이 든 컨테이너 이미지로 소스를 다루는 방법과 dubious ownership 오류를 다룹니다.', 'linux', '미들웨어'),
  (94, 'Git 처음부터 올리기: init, remote add, push 와 첫 오류들', 'Git 설정이 하나도 안 된 새 환경에서 `git init` → 사용자 설정 → `git remote add` → `git add` → `git commit` → `git push -u` 까지 처음부터 끝까지 해 보는 흐름을 익힙니다. 현장에서 가장 자주 만나는 첫 오류(사용자 미설정, 브랜치 이름 불일치, remote 중복, 첫 push 거절)와 .gitignore 를 처음 add 전에 정하는 습관까지 다룹니다. 원격은 샌드박스 안의 저장소로 대신합니다.', 'linux', 'Git'),
  (95, 'Git 문제 해결 상황집: 막혔을 때 빠져나오는 법', '현장에서 Git 이 막혔을 때 빠져나오는 법을 상황별로 익힙니다. 병합·rebase 를 중단하고 되돌리기, detached HEAD 에서 작업 살리기, 잘못된 브랜치에 한 커밋 옮기기, `.gitignore` 를 넣어도 계속 추적되는 파일 풀기, 삭제한 브랜치 복구, 문자열이 언제 들어왔는지 찾기, 비밀 정보를 커밋했을 때의 대응을 문제와 실습으로 다룹니다.', 'linux', 'Git'),
  (96, 'Git .gitignore: 올리면 안 되는 파일 다루기', '비밀 파일·빌드 산출물·로그를 저장소에 올리지 않는 법을 익힙니다. 패턴 문법(`*`, 폴더 `/`, 예외 `!`), 이미 추적 중인 파일을 `git rm --cached` 로 끊기, 어떤 규칙이 무시하는지 `git check-ignore -v` 로 찾기, 전역 무시 파일, 빈 폴더를 `.gitkeep` 으로 남기는 법을 문제와 실습으로 다룹니다.', 'linux', 'Git'),
  (97, '도커 문제 해결 상황집: 컨테이너가 안 뜰 때', '컨테이너가 바로 종료되거나, 포트가 충돌하거나, 디스크가 가득 찰 때 원인을 찾아 해결하는 법을 익힙니다. docker ps -a·logs·inspect 로 조사하고, 종료 코드 읽기, 포트·이름 충돌 풀기, 환경 변수 누락 고치기, 쌓인 컨테이너 정리, 재시작 정책을 문제와 실습으로 다룹니다.', 'docker', '도커'),
  (98, 'HAProxy 문제 해결 상황집: 503, DOWN, 안 뜰 때', '로드밸런서가 503 을 돌려주거나, 서버가 DOWN 이거나, 설정을 적용하지 못할 때 원인을 찾아 고치는 법을 익힙니다. 503·502·504 구분, 헬스체크 실패 사유(Layer4/Layer7) 읽기, stats CSV 로 DOWN 서버 찾기, 설정 검사(-c)로 오타 잡기, 포트 충돌 피하기, 끊김 없는 재적용(-sf)을 문제와 실습으로 다룹니다.', 'linux', '미들웨어'),
  (99, 'Redis 접속과 키 관리: 조회, 삭제, 이름 짓기', 'redis-cli 로 서버를 점검하고 키를 안전하게 다루는 기본기를 익힙니다. PING·TYPE·TTL 확인, 자료형에 맞는 읽기, KEYS 대신 SCAN, DEL 과 UNLINK, FLUSHDB·FLUSHALL 의 위험, 키 이름 규칙, INFO keyspace 읽기, 비밀번호 인증과 DB 번호 선택을 문제와 실습으로 다룹니다.', 'linux', '미들웨어'),
  (100, '동시성 기본기: 경쟁 상태, 락, 데드락, 멱등성', '여러 작업이 동시에 실행될 때 생기는 문제와 해결법을 익힙니다. 경쟁 상태(lost update)를 재현해 보고 flock 으로 막기, 중복 실행 방지, 데드락과 락 순서 통일, 낙관적·비관적 락, 멱등 키와 중복 이벤트 처리, 재시도와 백오프, 원자적 락(mkdir, SET NX)을 문제와 실습으로 다룹니다.', 'linux', '미들웨어'),
  (101, '이벤트 스트리밍 기본기: 컨슈머 그룹, 오프셋, 전달 보장, 순서', '이벤트 스트리밍(Kafka)을 안전하게 쓰기 위한 기본기를 익힙니다. 컨슈머 그룹과 리밸런싱, 오프셋 커밋과 자동 커밋의 함정, lag 읽기, at-least-once·at-most-once·exactly-once, 파티션 단위 순서와 키 설계, 멱등한 처리, DLQ, Outbox 패턴을 빈칸·순서·객관식으로 다룹니다.', 'quiz', '미들웨어'),
  (102, 'Redis 문제 해결 상황집: OOM, 연결 거부, 느린 명령', 'Redis 가 쓰기를 거부하거나 느려지거나 연결이 안 될 때 원인을 찾아 해결하는 법을 익힙니다. OOM(maxmemory 와 eviction 정책), Connection refused 와 포트 찾기, SLOWLOG 로 느린 명령 찾기, 만료 없이 쌓이는 키 정리, 연결 한도와 붙잡힌 연결 끊기를 문제와 실습으로 다룹니다.', 'linux', '미들웨어'),
  (103, 'Prometheus 알림 기본기: up, 알림 규칙, Alertmanager', 'Prometheus 로 서버를 감시하고 알림을 받는 기본기를 익힙니다. up 메트릭 읽기, 알림 규칙(expr, for, severity), 알림이 전달되는 흐름, 새 타깃 추가 절차, 히스토그램과 p95, Alertmanager 의 그룹핑·silence·라우팅을 빈칸·순서·객관식과 파일 실습으로 다룹니다.', 'linux', '미들웨어'),
  (104, 'Prometheus 문제 해결 상황집: 타깃 DOWN, 빈 쿼리, 알림 안 옴', 'Prometheus 로 감시하다 막혔을 때 원인을 찾는 법을 익힙니다. Targets 에러(connection refused, context deadline exceeded, 401)로 원인 가르기, 쿼리가 빈 결과일 때 레이블 확인, 로그에서 가장 흔한 수집 에러 찾기, promtool 오류 읽고 규칙 고치기, 알림이 라우트에 안 맞아 전달되지 않는 문제를 문제와 파일 실습으로 다룹니다.', 'linux', '미들웨어'),
  (105, '반복 입문: 같은 일을 컴퓨터에게 맡기기', '반복 작업 세트(35) 전에 가볍게 보는 입문입니다. 같은 일을 여러 번 시키는 이유, for 문의 모양, 와일드카드(*.log), seq, 한 줄씩 읽는 while read, 공백 파일 이름의 함정, 지우기 전에 echo 로 미리보기하는 습관을 쉬운 문제로 익힙니다.', 'quiz', '리눅스'),
  (106, '이름으로 통신 입문: 이름표, 전화번호부, 포트', '이름으로 통신하기(36) 전에 가볍게 보는 입문입니다. 왜 이름이 필요한지, /etc/hosts 와 DNS 의 차이, 이름을 찾는 순서, 포트 번호, Name or service not known 과 Connection refused 의 차이, 접속 장애를 좁히는 순서를 쉬운 문제로 익힙니다.', 'quiz', '리눅스'),
  (107, 'k8s 장애 읽기 입문: Pod 상태 한마디씩', '쉬운 장애 고치기(33) 전에 가볍게 보는 입문입니다. Running·Pending·ImagePullBackOff·CrashLoopBackOff 의 뜻, 막힌 Pod 를 보는 순서(get → describe → logs), Events 읽는 법, logs --previous, Pod 가 아니라 Deployment 를 고치는 이유를 쉬운 문제로 익힙니다.', 'quiz', 'k8s'),
  (108, 'k8s 통신 입문: Pod IP, Service, 이름', '통신 방법 익히기(37) 전에 가볍게 보는 입문입니다. Pod 마다 IP 가 있다는 것, IP 가 바뀌는 이유, 그래서 Service 가 필요한 이유, 이름으로 접속하는 길, 레이블과 selector, port 와 targetPort, 다른 네임스페이스 이름, 외부 접속 방식을 쉬운 문제로 익힙니다.', 'quiz', 'k8s'),
  (109, 'MariaDB 백업과 복원: 덤프 뜨고, 되살리고, 검증하기', 'MariaDB 를 안전하게 백업하고 복원하는 필수 기본기를 실제로 해 봅니다. mysqldump 로 덤프(--single-transaction)와 압축 덤프, 삭제된 DB 복구, 전체 덤프에서 테이블 하나만 복구, 새 DB 에 복원해 행 수 검증, 논리 백업과 물리 백업의 차이, 사용자·권한은 따로 옮겨야 하는 이유를 문제와 실습으로 다룹니다.', 'linux-db', '미들웨어'),
  (110, 'Vault 입문: 비밀을 맡기는 금고', 'Vault 를 처음 만나는 입문입니다. Vault 가 무엇인지, Sealed/Unseal 과 unseal 키를 나눠 갖는 이유, 처음 시작하는 순서(init → unseal → login), root 토큰을 다루는 법, KV 에 비밀 넣고 꺼내기, 정책(최소 권한), 토큰 TTL, 앱이 비밀을 안전하게 쓰는 흐름을 쉬운 문제로 익힙니다.', 'quiz', '미들웨어'),
  (111, 'Vault 백업과 복원: 스냅샷으로 되살리기', 'Vault 의 필수 운영 기본기입니다. 백업이 필요한 이유, raft snapshot save/restore, 스냅샷 파일을 민감하게 다루는 법, 복원 순서와 unseal 키 보관, cron 자동화, 백업을 다른 곳에 보관하기, 복원 연습, 유출된 비밀은 복원이 아니라 폐기·교체로 해결한다는 점을 문제로 익힙니다.', 'quiz', '미들웨어'),
  (112, 'Elasticsearch REST 기본기: curl 로 상태 보고 넣고 검색하기', 'Elasticsearch 를 curl 로 다루는 기본기를 익힙니다. 9200/9300 포트, _cat/health·_cat/indices 읽기, 문서 저장·조회 메서드, 색인 후 검색 순서, _search 응답(took, hits) 읽기, query DSL, 오류 응답(index_not_found_exception) 읽기, _bulk 형식 만들기를 문제와 파일 실습으로 다룹니다.', 'linux', '미들웨어'),
  (113, 'Elasticsearch 문제 해결 상황집: yellow/red, 미할당 샤드, 디스크', 'Elasticsearch 가 yellow/red 가 되거나 쓰기가 막힐 때 원인을 찾아 해결하는 법을 익힙니다. 클러스터 진단 순서, yellow 와 red 의 의미, 디스크 워터마크 3단계, read-only 블록 해제, allocation/explain 읽기(NODE_LEFT, disk_threshold), 미할당 샤드 찾기, 오래된 인덱스 정리 명령 만들기를 문제와 파일 실습으로 다룹니다.', 'linux', '미들웨어');
